import { createRequire } from "node:module";
import { readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { join } from "node:path";
const REPO = process.env.REPO;
const require = createRequire(join(REPO, "package.json"));
const { chromium } = require("playwright");
const { decode } = require("cbor-x");
const { routeAccessHeaders } = await import(join(REPO, "npm-scripts/env.mjs"));

const ORIGIN = process.env.ORIGIN ?? "https://stallion.matthijs-f49.workers.dev";
const [, , label, scenario, boardArg, mode = "wheel"] = process.argv;
const OUT = join(process.env.HOME, "development/.tmp/stallion-zoomcrash", label);
mkdirSync(OUT, { recursive: true });
const randomBoardId = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v.toString(36).padStart(25, "0");
};
const boardId = boardArg && boardArg !== "new" ? boardArg : randomBoardId();

const rssTree = (root) => {
  const kids = new Map();
  for (const pid of readdirSync("/proc").filter((d) => /^\d+$/.test(d))) {
    try {
      const stat = readFileSync(`/proc/${pid}/stat`, "utf8");
      const ppid = Number(stat.slice(stat.lastIndexOf(")") + 2).split(" ")[1]);
      if (!kids.has(ppid)) kids.set(ppid, []);
      kids.get(ppid).push(Number(pid));
    } catch {}
  }
  let total = 0;
  const walk = (pid) => {
    try {
      const m = readFileSync(`/proc/${pid}/status`, "utf8").match(/VmRSS:\s+(\d+)/);
      if (m) total += Number(m[1]);
    } catch {}
    for (const k of kids.get(pid) ?? []) walk(k);
  };
  walk(root);
  return Math.round(total / 1024);
};

const gpu = process.env.GPU === "1";
const browser = await chromium.launch({ headless: true, ...(gpu ? { args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--enable-gpu-rasterization", "--ignore-gpu-blocklist", "--enable-accelerated-2d-canvas"] } : {}) });
if (gpu) { const b = await browser.newBrowserCDPSession(); const info = await b.send("SystemInfo.getInfo"); console.log("GPU", JSON.stringify(info.gpu.featureStatus)); }
const pid = process.pid;
const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
await routeAccessHeaders(context, ORIGIN);
await context.addInitScript(() => {
  const s = (window.__stats = { fill: 0, stroke: 0, fillRect: 0, strokeRect: 0, ellipse: 0, lineTo: 0, getStroke: 0, rafMs: [], gaps: [], frames: 0, last: 0 });
  const P = CanvasRenderingContext2D.prototype;
  for (const name of ["fill", "stroke", "fillRect", "strokeRect", "ellipse", "lineTo"]) {
    const orig = P[name];
    P[name] = function (...a) { s[name]++; return orig.apply(this, a); };
  }
  const L = Path2D.prototype.lineTo;
  Path2D.prototype.lineTo = function (...a) { s.lineTo++; return L.apply(this, a); };
  const raf = window.requestAnimationFrame.bind(window);
  window.requestAnimationFrame = (cb) => raf((t) => { const t0 = performance.now(); cb(t); s.rafMs.push(performance.now() - t0); s.frames++; if (s.last) s.gaps.push(t0 - s.last); s.last = t0; });
});
const page = await context.newPage();
const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));
const cdp = await context.newCDPSession(page);
await cdp.send("Performance.enable");
await cdp.send("Network.enable");
const ws = { recv: 0, recvBytes: 0, sent: {}, recvKinds: {}, lastView: undefined, subscribed: new Set(), snapshots: new Set() };
cdp.on("Network.webSocketFrameReceived", ({ response }) => {
  ws.recv++;
  const buf = Buffer.from(response.payloadData, "base64");
  ws.recvBytes += buf.length;
  try { const f = decode(buf); ws.recvKinds[f.kind] = (ws.recvKinds[f.kind] ?? 0) + 1; if (f.kind === "Snapshot") ws.snapshots.add(f.tileKey); if (f.kind === "Hints") { try { ws.lastHints = decode(f.payload)?.length; } catch {} } } catch {}
});
cdp.on("Network.webSocketFrameSent", ({ response }) => {
  try {
    const f = decode(Buffer.from(response.payloadData, "base64"));
    ws.sent[f.kind] = (ws.sent[f.kind] ?? 0) + 1;
    if (f.kind === "View") ws.lastView = decode(f.payload);
    if (f.kind === "Subscribe") ws.subscribed.add(f.tileKey);
    if (f.kind === "Unsubscribe") ws.subscribed.delete(f.tileKey);
  } catch {}
});

await page.goto(`${ORIGIN}/b/${boardId}`, { waitUntil: "load" });
await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
await page.waitForTimeout(2500);
const W = 1440, H = 900, cx = W / 2, cy = H / 2;
if (scenario === "drawn") {
  for (let s = 0; s < 6; s++) {
    const y0 = 250 + s * 70;
    await page.mouse.move(350, y0);
    await page.mouse.down();
    for (let i = 1; i <= 40; i++) await page.mouse.move(350 + i * 18, y0 + Math.sin(i / 4) * 40, { steps: 1 });
    await page.mouse.up();
  }
  await page.locator("[data-toolbar-flip]").click();
  await page.waitForTimeout(500);
  const pal = page.locator(".toolbar[data-layout=\"Palette\"]");
  const btn = (name) => pal.getByRole("button", { name, exact: true });
  const drag = async (x0, y0, x1, y1) => { await page.mouse.move(x0, y0); await page.mouse.down(); await page.mouse.move(x1, y1, { steps: 10 }); await page.mouse.up(); };
  await btn("Ellipse").click(); await drag(cx - 300, cy - 200, cx + 300, cy + 200);
  await btn("Rectangle").click(); await drag(cx - 250, cy - 150, cx + 250, cy + 150);
  await btn("Dashed style").click(); await btn("Ellipse").click(); await drag(cx - 200, cy - 100, cx + 200, cy + 100);
  await btn("Rectangle").click(); await btn("Rectangle").click();
  await btn("96 px pencil").click(); await btn("Highlighter style").click();
  await drag(cx - 400, cy + 50, cx + 400, cy - 50);

  await page.waitForTimeout(1500);
}
if (process.env.ANCHOR) { const [ax, ay] = process.env.ANCHOR.split(",").map(Number); await page.mouse.move(ax, ay); }
const level = async () => Number(await page.locator(".level-chip").innerText());
await page.screenshot({ path: join(OUT, `level-0.png`) });
const rows = [];
const snap = async (lvl) => {
  await page.evaluate(() => { const s = window.__stats; for (const k of Object.keys(s)) s[k] = Array.isArray(s[k]) ? [] : 0; });
  const recv0 = ws.recv, bytes0 = ws.recvBytes, t0 = Date.now();
  for (let i = 0; i < 30; i++) { await page.mouse.wheel(0, i % 2 ? 0.5 : -0.5); await page.waitForTimeout(33); }
  const secs = (Date.now() - t0) / 1000;
  const st = await page.evaluate(() => window.__stats);
  const m = Object.fromEntries((await cdp.send("Performance.getMetrics")).metrics.map((x) => [x.name, x.value]));
  const frames = st.frames || 1;
  const sorted = [...st.rafMs].sort((a, b) => a - b);
  const v = ws.lastView;
  const row = {
    level: lvl,
    heapMB: +(m.JSHeapUsedSize / 1048576).toFixed(1),
    rssMB: pid ? rssTree(pid) : null,
    frames,
    gapMaxMs: +Math.max(0, ...st.gaps).toFixed(1),
    rafAvgMs: +(st.rafMs.reduce((a, b) => a + b, 0) / frames).toFixed(2),
    rafP95Ms: +(sorted[Math.floor(sorted.length * 0.95)] ?? 0).toFixed(2),
    rafMaxMs: +(sorted.at(-1) ?? 0).toFixed(2),
    callsPerFrame: +((st.fill + st.stroke + st.fillRect + st.strokeRect) / frames).toFixed(1),
    lineToPerFrame: Math.round(st.lineTo / frames),
    wsRecvPerS: +((ws.recv - recv0) / secs).toFixed(1),
    wsKBPerS: +((ws.recvBytes - bytes0) / 1024 / secs).toFixed(1),
    subscribed: ws.subscribed.size,
    snapshotTiles: ws.snapshots.size,
    viewW: v ? +(v.maxX - v.minX).toPrecision(4) : null,
    viewH: v ? +(v.maxY - v.minY).toPrecision(4) : null,
    zoom: v?.zoom,
  };
  rows.push(row);
  console.log(JSON.stringify(row));
  await page.screenshot({ path: join(OUT, `level${lvl}.png`) });
};
await snap(await level());
let profiling = false;
await page.evaluate(() => { const s = window.__stats; for (const k of Object.keys(s)) s[k] = Array.isArray(s[k]) ? [] : 0; });
for (let target = -1; target >= Number(process.env.DEEPEST ?? -9); target--) {
  await page.evaluate(() => { const s = window.__stats; for (const k of Object.keys(s)) s[k] = Array.isArray(s[k]) ? [] : 0; });
  if (target === -7 && !profiling) { await cdp.send("Profiler.enable"); await cdp.send("Profiler.start"); profiling = true; }
  if (mode === "chip") {
    await page.locator(".level-chip").click();
    await page.getByRole("option", { name: new RegExp(`^Level ${target}(,|$)`) }).click();
    await page.waitForTimeout(600);
  } else {
    let guard = 0;
    while ((await level()) > target && guard++ < 200) {
      for (let k = 0; k < 10; k++) await page.mouse.wheel(0, -10);
      await page.waitForTimeout(16);
    }
  }
  await page.waitForTimeout(800);
  const tr = await page.evaluate(() => { const s = window.__stats; return { frames: s.frames, maxRaf: Math.max(0, ...s.rafMs), gapMax: Math.max(0, ...s.gaps) }; });
  console.log("transit", target, JSON.stringify(tr), "views", ws.sent.View, "recv", ws.recv, "rss", rssTree(pid));
  await snap(await level());
}
if (profiling) {
  const { profile } = await cdp.send("Profiler.stop");
  writeFileSync(join(OUT, "zoom-7-to-9.cpuprofile"), JSON.stringify(profile));
  const self = new Map();
  const byId = new Map(profile.nodes.map((n) => [n.id, n]));
  const dt = profile.timeDeltas; const counts = new Map();
  profile.samples.forEach((id, i) => counts.set(id, (counts.get(id) ?? 0) + (dt[i] ?? 0)));
  for (const [id, us] of counts) { const n = byId.get(id); const key = `${n.callFrame.functionName || "(anon)"} ${n.callFrame.url.split("/").pop()}:${n.callFrame.lineNumber}`; self.set(key, (self.get(key) ?? 0) + us); }
  const top = [...self].sort((a, b) => b[1] - a[1]).slice(0, 12).map(([k, us]) => `${(us / 1000).toFixed(0)}ms ${k}`);
  console.log("PROFILE top self:\n" + top.join("\n"));
}
writeFileSync(join(OUT, "rows.json"), JSON.stringify({ boardId, scenario, mode, rows, errors, sentKinds: ws.sent, recvKinds: ws.recvKinds }, null, 1));
console.log("board", boardId, "errors", errors.length, errors.slice(0, 5), "sent", ws.sent, "recv", ws.recvKinds);
await browser.close();
import { createRequire } from "node:module";
import { join } from "node:path";
const require = createRequire(join(process.env.REPO, "package.json"));
